def is_palindrome(s):
    clean = [ch.lower() for ch in s if ch.isalnum()]
    return clean == clean[::-1]

alt:
def is_palindrome(s):
    clean = "".join(ch for ch in s.lower() if ch.isalnum())
    i, j = 0, len(clean) - 1
    while i < j:
        if clean[i] != clean[j]:
            return False
        i += 1
        j -= 1
    return True
